package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.JDKRandomGenerator;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getResult_TriageGen0Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = new JDKRandomGenerator();
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 10, mockGenerator);
    }

    /**
     * Tests that getResult() correctly returns the value provided by the underlying optimizer.
     * This covers the success path for the getResult method.
     */
    @Test
    public void testGetResultReturnsCorrectValue() {
        double expectedResult = 42.0;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("getResult should return the value from the underlying optimizer", expectedResult, actualResult, 1e-15);
    }

    /**
     * Tests that getResult() returns a specific value when the optimizer returns a different value.
     * This ensures there is no hardcoded or incorrect mapping.
     */
    @Test
    public void testGetResultWithDifferentValue() {
        double expectedResult = -123.456;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("getResult should return the exact double value provided by the optimizer", expectedResult, actualResult, 1e-15);
    }

    /**
     * Tests the behavior when the underlying optimizer returns NaN.
     * This ensures the method propagates NaN correctly.
     */
    @Test
    public void testGetResultReturnsNaN() {
        when(mockOptimizer.getResult()).thenReturn(Double.NaN);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("getResult should return NaN if the underlying optimizer returns NaN", Double.NaN, actualResult, 0.0);
    }

    /**
     * Tests the behavior when the underlying optimizer returns Infinity.
     */
    @Test
    public void testGetResultReturnsInfinity() {
        double expectedResult = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        double actualResult = multiStartOptimizer.getResult();

        assertEquals("getResult should return Infinity if the underlying optimizer returns Infinity", expectedResult, actualResult, 0.0);
    }
}
